use super::*;
use semio_framework_os_kernel::{sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteValue},ArtifactSqliteSnapshot};

fn fixture()->MdSnapshot{pack::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap()}
fn roundtrip(snapshot:&MdSnapshot)->MdSnapshot{let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let bytes=export_sqlite_database(&database,limits,&mut |_|true).unwrap();let database=import_sqlite_database(&bytes,limits,&mut |_|true).unwrap();MdSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap()}

#[test]
fn sqlite_snapshot_md_all_semantic_variants_and_optional_states(){let snapshot=fixture();assert_eq!(roundtrip(&snapshot),snapshot);let actual:serde_json::Value=serde_json::from_str(&pack::json::to_json_string(&protocol::ToValue::to_value(&snapshot))).unwrap();assert_eq!(actual,serde_json::from_str::<serde_json::Value>(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap());assert_eq!(roundtrip(&MdSnapshot{schema:"".into(),blocks:Vec::new()}),MdSnapshot{schema:"".into(),blocks:Vec::new()});}

#[test]
fn sqlite_snapshot_md_independent_sqlite_queries_and_edits_tree_entities(){
 use std::{io::Write,process::{Command,Stdio}};let limits=SqliteDatabaseLimits::default();let mut expected=fixture();let database=expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let bytes=export_sqlite_database(&database,limits,&mut |_|true).unwrap();
 let script="import {Database} from 'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const head=db.query('SELECT h.level,t.text FROM md_document_block b JOIN md_heading h ON h.id=b.block_id JOIN md_block_inline i ON i.block_id=h.id JOIN md_text t ON t.id=i.inline_id WHERE b.ordinal=0 AND i.ordinal=0').get();if(head.level!==255||head.text!=='Alpha 世界\\0')throw Error('semantic heading');if(db.query('SELECT start FROM md_list WHERE start IS NOT NULL').get().start!==4294967295)throw Error('u32');db.query('UPDATE md_text SET text=? WHERE id=(SELECT inline_id FROM md_block_inline WHERE block_id=(SELECT block_id FROM md_document_block WHERE ordinal=0) AND ordinal=0)').run('edited 世界');db.query('UPDATE md_heading SET level=0').run();await Bun.write(Bun.stdout,db.serialize());db.close();";
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let result=child.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));let database=import_sqlite_database(&result.stdout,limits,&mut |_|true).unwrap();let MdBlock::Heading{level,inlines}=&mut expected.blocks[0]else{panic!()};*level=0;let MdInline::Text{text}=&mut inlines[0]else{panic!()};*text="edited 世界".into();assert_eq!(MdSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);
}

#[test]
fn sqlite_snapshot_md_rejects_invalid_ownership_ordinals_tags_and_bounds(){let snapshot=fixture();let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for(table,column,value)in [("md_heading",1,SqliteValue::Integer(256)),("md_block",1,SqliteValue::Text("paragraph".into())),("md_document_block",2,SqliteValue::Integer(99)),("md_block_inline",1,SqliteValue::Integer(999))]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[0].values[column]=value;assert!(MdSnapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err(),"{table}");}assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:1,..limits})).is_err());assert!(MdSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:16,..limits})).is_err());}

#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_md_actual_declaration_exports_full_owned_tree_over_io(){use semio_framework_os_kernel::{io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}},sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotPhase}};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("MD SQLite declaration").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let dialect:ArtifactDialect=crate::MD_DIALECT.into();let snapshot=fixture();let mut phases=Vec::new();let bytes=io_export_sqlite_snapshot(&dialect,&snapshot,SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut |event|{phases.push(event.phase);true}).await.unwrap().value;assert_eq!(io_import_sqlite_snapshot::<MdSnapshot>(&dialect,&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value,snapshot);assert!(!phases.iter().any(|phase|matches!(phase,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}

#[test]
fn sqlite_snapshot_md_iterative_tree_supports_1024_owned_levels(){let case=depth_case();let mut inline=MdInline::Text{text:case.leaf.clone()};for _ in 0..case.depth{inline=MdInline::Strong{inlines:vec![inline]};}let mut block=MdBlock::Paragraph{inlines:vec![inline]};for _ in 0..case.depth{block=MdBlock::BlockQuote{blocks:vec![block]};}let restored=roundtrip(&MdSnapshot{schema:"deep tree".into(),blocks:vec![block]});let mut block=&restored.blocks[0];for _ in 0..case.depth{let MdBlock::BlockQuote{blocks}=block else{panic!("quote depth lost")};block=&blocks[0];}let MdBlock::Paragraph{inlines}=block else{panic!()};let mut inline=&inlines[0];for _ in 0..case.depth{let MdInline::Strong{inlines}=inline else{panic!("inline depth lost")};inline=&inlines[0];}assert_eq!(inline,&MdInline::Text{text:case.leaf});}

#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_commonmark_actual_erased_capability_preserves_owned_binary_and_text(){use semio_framework_os_kernel::{io::{ArtifactDialect,IoPayload},sqlite_snapshot::SnapshotEncoding};let mut snapshot=fixture();snapshot.schema="owned 世界\0".into();semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("commonmark erased SQLite").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let codec=store::document_codec(<MdSnapshot as store::ArtifactDsl>::envelope_id()).await.unwrap().unwrap();let provider=codec.snapshot_sqlite.as_ref().unwrap();let dialect=ArtifactDialect{artifact_kind:"s.stdio.md".into(),standard:"commonmark".into(),subset:"*".into()};let expected=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(<MdSnapshot as store::ArtifactPack>::encode_pack_with(&snapshot,&store::PackEncodeOptions::default()).unwrap()),SnapshotEncoding::Text=>IoPayload::Text(<MdSnapshot as store::ArtifactDsl>::print_dsl(&snapshot))};let database=(provider.export)(&codec.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(database,expected);let restored=(provider.import)(&codec.schema,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let restored=match restored{IoPayload::Binary(bytes)=><MdSnapshot as store::ArtifactPack>::decode_pack(&bytes).unwrap(),IoPayload::Text(text)=><MdSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap()};assert_eq!(restored.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);}}

#[test]
fn sqlite_snapshot_commonmark_owned_encoding_preflight_checks_bounds_before_allocation(){use semio_framework_os_kernel::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotPhase};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut snapshot=fixture();snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1024,..SqliteDatabaseLimits::default()})).unwrap_err().contains("native encoding exceeds file byte limit"));snapshot.blocks=vec![MdBlock::HtmlBlock{raw:"x".repeat(131073)}];let mut reached=false;assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |event|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>0{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);}}

#[test]
fn sqlite_snapshot_commonmark_logical_erased_records_preserve_1024_tree_levels(){use semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding;let case=depth_case();let mut inline=MdInline::Text{text:case.leaf.clone()};for _ in 0..case.depth{inline=MdInline::Strong{inlines:vec![inline]}}let mut block=MdBlock::Paragraph{inlines:vec![inline]};for _ in 0..case.depth{block=MdBlock::BlockQuote{blocks:vec![block]}}let snapshot=MdSnapshot{schema:"deep owned World".into(),blocks:vec![block]};let limits=SqliteDatabaseLimits::default();let expected=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let codec=(crate::native_codecs()[0].codec)();assert_eq!(codec.pack_schema_hash,store::schema_hash(&<MdSnapshot as store::ArtifactPack>::record_spec().unwrap()));let provider=codec.snapshot_sqlite.expect("actual CommonMark owned provider");let dialect=semio_framework_os_kernel::io_schema::ArtifactDialect{artifact_kind:"s.stdio.md".into(),standard:"commonmark".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=(provider.import)(&codec.schema,&dialect,expected.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let restored=(provider.export)(&codec.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert_eq!(restored,expected)}}


#[test]
fn sqlite_snapshot_commonmark_neutral_exact_coordinate_guard_and_identity(){#[derive(value_derive::FromValue)]#[value(rename_all="camelCase")]struct Coordinates{sqlite_dialect:store::io_schema::ArtifactDialect,invalid_sqlite_dialects:Vec<store::io_schema::ArtifactDialect>}let coordinates:Coordinates=pack::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🧭️dialects/🔣️.json")).unwrap();let snapshot=fixture();let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();snapshot.validate_sqlite_snapshot_subset(&coordinates.sqlite_dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for dialect in coordinates.invalid_sqlite_dialects{assert!(snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}let mut changed=database.clone();changed.table_mut("md_document").unwrap().rows[0].values[1]=SqliteValue::Text("different owned schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&coordinates.sqlite_dialect,&changed,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(snapshot.validate_sqlite_snapshot_subset(&coordinates.sqlite_dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());}

