struct DepthCase{depth:usize,leaf:String}
fn depth_case()->DepthCase{pack::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/📏️depth/🔣️.json")).unwrap()}

#[test]
fn sqlite_snapshot_commonmark_handwritten_logical_text_refuses_cycles_reuse_orphans_and_mixed_variants(){let valid=r#"schema="owned text" roots=[0] blocks=[kind=paragraph inlines=[0] items=[] blocks=[]] inlines=[kind=strong inlines=[]]"#;let snapshot=<MdSnapshot as store::ArtifactDsl>::parse_dsl(valid).unwrap();assert_eq!(snapshot.blocks,vec![MdBlock::Paragraph{inlines:vec![MdInline::Strong{inlines:Vec::new()}]}]);for invalid in[valid.replace("kind=strong inlines=[]","kind=strong inlines=[0]"),valid.replace("roots=[0]","roots=[0 0]"),valid.replace("kind=paragraph",r#"kind=paragraph raw="unowned text""#),valid.replace("kind=strong inlines=[]","kind=strong inlines=[] kind=soft-break inlines=[]")]{assert!(<MdSnapshot as store::ArtifactDsl>::parse_dsl(&invalid).is_err(),"{invalid}");}let envelope=store::semio_format::SemioEnvelope::from_envelope_id("stdio.gltf",store::semio_format::Component::Dsl,1).unwrap();assert!(<MdSnapshot as store::ArtifactDsl>::parse_dsl(&store::semio_format::wrap_text(&envelope,valid)).is_err());}
